import{_ as o,o as s,c as t,a2 as d}from"./chunks/framework.CF-TnfK-.js";const u=JSON.parse('{"title":"Design tokens","description":"","frontmatter":{},"headers":[],"relativePath":"design/README.md","filePath":"design/README.md"}'),a={name:"design/README.md"};function i(n,e,c,h,r,p){return s(),t("div",null,[...e[0]||(e[0]=[d(`<h1 id="design-tokens" tabindex="-1">Design tokens <a class="header-anchor" href="#design-tokens" aria-label="Permalink to &quot;Design tokens&quot;">​</a></h1><p><code>tokens.json</code> is the single source for Coach Poulpy&#39;s colours, mood shades, type scale, spacing, radius and motion. Edit it, then regenerate the platform files:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> design/build-tokens.mjs</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Generated file</th><th>Used by</th></tr></thead><tbody><tr><td><code>app-android/.../ui/PoulpyTokens.kt</code></td><td><code>CoachPoulpyTheme</code> (Material 3 colour scheme, typography, shapes) plus <code>PoulpyPalette</code>, <code>PoulpyMood</code>, <code>PoulpySpace</code>, <code>PoulpyRadius</code>, <code>PoulpyMotion</code></td></tr><tr><td><code>app-ios/CoachPoulpy/Theme/PoulpyTokens.swift</code></td><td><code>PoulpyColor</code> (light and dark), <code>PoulpyPalette</code>, <code>PoulpyMood</code>, <code>PoulpyFont</code>, <code>PoulpySpace</code>, <code>PoulpyRadius</code>, <code>PoulpyMotion</code></td></tr><tr><td><code>app-ios/.../AccentColor.colorset/Contents.json</code></td><td>The iOS accent colour (buttons, links, toggles)</td></tr><tr><td><code>web/ui/src/tokens.css</code></td><td>CSS custom properties (<code>--cp-*</code>), with dark values under <code>prefers-color-scheme</code>, and <code>cp-theme-light</code> / <code>cp-theme-dark</code> to pin one theme on part of a page. The websites&#39; DaisyUI theme (<code>web/ui/src/theme.css</code>) points at them (<a href="./../docs/adr/0023-the-websites-share-one-vue-and-daisyui-design-system">ADR 0023</a>)</td></tr></tbody></table><p>CI runs <code>node design/build-tokens.mjs --check</code> and fails if a generated file no longer matches <code>tokens.json</code>.</p><p>Colour rules:</p><ul><li>The <code>poulpy</code> colours (blue, ember, ink) are the mascot&#39;s fabric and are the same in light and dark.</li><li>The blue side (<code>mood.proud</code>, <code>mood.happy</code>, <code>mood.recovering</code>) means the plan is on track; the ember side (<code>mood.annoyed</code>, <code>mood.grumpy</code>, <code>mood.fuming</code>) means a session slipped.</li><li>The plush blue and ember are too light for white text: buttons use <code>primary</code> (lagoon 600) and <code>grumpy</code> (ember 600).</li><li><code>error</code> is a crimson, always shown with an icon and text, so it is never confused with a grumpy Poulpy.</li></ul><p>The brand fonts are Baloo 2 (headings) and Nunito (body). The website loads them from Google Fonts. The apps bundle one static file per weight listed under <code>font</code> in <code>tokens.json</code>, in <code>app-android/src/main/res/font</code> and <code>app-ios/CoachPoulpy/Fonts</code>. After changing those weights, rebuild the files and the theme:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fonttools</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> design/fonts/build-fonts.py</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> design/build-tokens.mjs</span></span></code></pre></div><p>On iOS, also list any new file under <code>UIAppFonts</code> in <code>Info.plist</code>. Views use <code>.font(.poulpy(.headline))</code> instead of <code>.font(.headline)</code> to get the system text styles in the brand fonts. Both fonts are under the SIL Open Font License (<code>design/fonts/OFL-*.txt</code>).</p><h2 id="body-map-figures" tabindex="-1">Body map figures <a class="header-anchor" href="#body-map-figures" aria-label="Permalink to &quot;Body map figures&quot;">​</a></h2><p><code>build-body-map.mjs</code> draws the front and back muscle chart in both builds (wider shoulders, wider hips) and writes it into the profile screens&#39; stories (<code>profile-pain-sheet</code>, <code>profile-body-figure-sheet</code>) and into <code>design/body-map.json</code>, which the apps read. The muscle outlines come from <code>design/body-map-source/parts.json</code>, adapted from the MIT-licensed <a href="https://github.com/hugobonifay/body-map" target="_blank" rel="noreferrer">hugobonifay/body-map</a> (see <code>design/body-map-source/NOTICE.md</code>); the script turns them into plain curves, names each muscle, stretches the builds and leaves the skin transparent. To change a muscle, edit the script or the source outlines, then run:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> design/build-body-map.mjs</span></span></code></pre></div><h2 id="poulpy-s-drawings" tabindex="-1">Poulpy&#39;s drawings <a class="header-anchor" href="#poulpy-s-drawings" aria-label="Permalink to &quot;Poulpy&#39;s drawings&quot;">​</a></h2><p><code>build-poulpy.mjs</code> draws the themed (one-colour) layers of the Android app icons with the brand book&#39;s own drawing code. His moods, poses, loader and app icons are pictures of the 3D model, from <code>build-poulpy-pictures.mjs</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> design/build-poulpy.mjs</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Generated file</th><th>Used by</th></tr></thead><tbody><tr><td><code>design/poulpy-3d/moves/pose_champion_cheer_{1,2,3}.png</code></td><td>the champion&#39;s tap on Home (three jumps, medal and confetti, ending on his still picture), 72 frames in three sheets of 24, 497 × 472 pixels a frame, from <code>build-poulpy-pictures.mjs</code></td></tr><tr><td><code>design/poulpy-3d/moves/pose_champion_party_{1,2,3,4}.png</code></td><td>the champion on the finished screen, who never stops: a seamless loop of four jumps, 96 frames in four sheets of 24, same frame size, from <code>build-poulpy-pictures.mjs</code></td></tr><tr><td><code>design/poulpy-3d/moves/mood_move_&lt;name&gt;.png</code></td><td>how the happy Poulpy loses patience on Home: the turns between his moods (<code>to_annoyed</code>, <code>to_fuming</code>, <code>calm_down</code>, <code>back_to_normal</code>) and his answers to a tap while annoyed or fuming (<code>shake</code>, <code>shudder</code>), one sheet each, 34 to 46 frames at 24 a second, from <code>design/poulpy-3d/moods.mjs</code> by <code>build-poulpy-pictures.mjs</code></td></tr><tr><td><code>design/poulpy-3d/moves/mood_{happy,proud}_{left,right}.png</code>, <code>mood_happy_spin.png</code></td><td>Home&#39;s moves (a jump leaning each way, and the high jump with a full turn for happy), 30 frames each in one sheet, for every platform: the website, Android (assets) and iOS (bundle) read these files, from <code>build-poulpy-pictures.mjs</code></td></tr><tr><td><code>design/poulpy-3d/loader/{swing,clockwise}.png</code></td><td>The loader, once for every platform: the website, Android (as assets) and iOS (in the bundle) all read these two files, from <code>build-poulpy-pictures.mjs</code></td></tr><tr><td><code>app-android/src/main/res/drawable-nodpi/poulpy_*.png</code></td><td>His moods and poses as Android pictures (<code>R.drawable.poulpy_pose_champion</code>), from <code>build-poulpy-pictures.mjs</code></td></tr><tr><td><code>app-ios/CoachPoulpy/Assets.xcassets/Poulpy/Poulpy{Mood,Pose}*.imageset</code></td><td>His moods and poses as iOS 3x pictures (<code>Image(&quot;PoulpyPoseChampion&quot;)</code>), from <code>build-poulpy-pictures.mjs</code></td></tr><tr><td><code>app-android/src/main/res/drawable-nodpi/ic_launcher_[&lt;id&gt;_]foreground.png</code>, <code>drawable/ic_launcher_background.xml</code>, <code>drawable/ic_launcher_[&lt;id&gt;_]monochrome.xml</code>, <code>mipmap-anydpi-v26/ic_launcher[_&lt;id&gt;].xml</code></td><td>The Android launcher icon: an adaptive icon with a Deep sea background, a picture of Poulpy and a themed (monochrome) silhouette layer</td></tr><tr><td><code>app-ios/CoachPoulpy/Assets.xcassets/AppIcon[&lt;Id&gt;].appiconset</code></td><td>The iOS app icon: 1024 px PNGs for light, dark and tinted; the light and dark are alike, on Deep sea. The alternate icons Settings › App icon offers (<code>proud</code>, <code>annoyed</code>, <code>grumpy</code>, <code>champion</code>, <code>cocky</code>) are the sets with an id</td></tr></tbody></table><p><strong>The moves of Home</strong> are baked the same way. A tap on Home&#39;s Poulpy plays a move at random: for happy and proud his jump leaning to one side or the other, and for happy also a high jump with a full turn on himself (<code>createJump</code> with Height 1, heavy arms and an exact 360° step, as tuned on the workshop&#39;s &quot;Jumping around&quot; page; <code>spin</code>): <code>build-poulpy-pictures.mjs</code> poses the model with <code>posePoulpy</code> (in <code>motion.mjs</code>, the workshop rig&#39;s maths in plain matrices) from <code>createJump</code>, paints 30 frames at 24 a second with <code>paintPoulpy</code>, and writes one sheet for each mood and move to <code>design/poulpy-3d/moves/mood_&lt;mood&gt;_&lt;left|right|spin&gt;.png</code> (6 across and 5 down, each frame 355 × 336 pixels: the still picture&#39;s shot at 3 pixels to a point, on a canvas 24 points bigger every way so the jump is not cut off). The sides are as the viewer sees him. The website, Android (assets) and iOS (bundle) read those files from there; <code>PoulpyMoves</code> in the shared code says which pictures move, which sheet and which frame, and the script checks its numbers against it. With reduced motion a tap does nothing.</p><p><strong>The champion&#39;s celebration</strong> on the end-of-session screen is baked the same way, from <code>createCheer</code> (three jumps of joy, his medal swinging on its hinge, confetti flying from each take-off): <code>posePoulpy</code> also places the medal and turns each piece of confetti, a small flat card in the room. 72 frames at 20 a second (3.6 s) go to <code>design/poulpy-3d/moves/pose_champion_cheer_&lt;1-3&gt;.png</code>, 24 frames to a sheet (6 across and 4 down, each frame 497 × 472 pixels: the still picture&#39;s shot at 1.2 pixels to a point, on a canvas 110 pixels bigger every way for the confetti), so no sheet is bigger than a phone&#39;s graphics chip takes. The confetti shrinks away in the last 0.7 s and the last frame is his still picture exactly, so he settles on it without a jump; this is the tap on Home. On the finished screen he never pauses: <code>createCheer({ cycle })</code> repeats the same four bursts, and with the same pauses (<code>PARTY</code> in the script) the whole state comes back exactly every 4.8 s, so 96 frames (<code>pose_champion_party_&lt;1-4&gt;.png</code>) loop with no seam and no confetti fade. <code>PoulpyCheer</code> and <code>PoulpyParty</code> in the shared code say which sheet and which frame, and the script checks their numbers against them.</p><p>Moods and poses are 744 × 678 pictures (the 3x of a 248 × 226 frame), so they can replace each other without moving. The loader is in <code>design/poulpy-3d/loader</code>, and only there: <code>swing.png</code> has the 48 frames of one cycle (8 across and 6 down, each a 240 px square) and <code>clockwise.png</code> is the one picture of the clockwise version, whose tentacles trail the same all the time. They show Poulpy&#39;s outline seen from straight below, with wider, shorter tentacles hanging loose on his arm springs, in the brand blue, see-through. The website, Android (as assets) and iOS (in the bundle) read those two files. <code>PoulpyLoader</code> on Android and iOS shows the frame of the moment and turns it, once every 3.6 s (12 s when animations are reduced), as <code>LoaderSwing</code> of the shared code says. It replaces the old Spinning pose. CI runs the generator with <code>--check</code> too. The shared <code>PoulpyDrawing</code> enum names each drawing, and <code>PoulpyCoach</code> picks which one Today shows.</p><p>The app icon is the 3D happy blue Poulpy on Deep sea (<code>theme.dark.background</code>), the same in light and dark, so it works whichever theme the phone is in; the tinted iOS icon is its greyscale. On iOS he is scaled to fill 80 % of the square. On Android, he is scaled so his farthest point sits on the 66 dp circle every launcher mask keeps; the themed icon is still his drawn silhouette at half strength with the eyes and smile at full. The pictures are painted in plain JavaScript so every machine gets the same pixels; <code>--check</code> compares those pixels, not the compressed bytes.</p><p>The alternate icons use the mood or pose picture of the same name, scaled the same way, so a pose with props or confetti draws Poulpy smaller. Their ids are those of <code>AppIcon</code> in the shared code and never change. Android switches between launcher aliases in the manifest; iOS lists the sets in <code>ASSETCATALOG_COMPILER_ALTERNATE_APPICON_NAMES</code> in <code>app-ios/project.yml</code>.</p><h2 id="poulpy-in-3d" tabindex="-1">Poulpy in 3D <a class="header-anchor" href="#poulpy-in-3d" aria-label="Permalink to &quot;Poulpy in 3D&quot;">​</a></h2><p><code>poulpy-3d/model.mjs</code> describes Poulpy&#39;s 3D shape in plain JavaScript, with no dependency: the proportions (<code>SHAPE</code>), his faces (<code>FACES</code>), his six moods (<code>MOODS</code>) and how he is lit and shaded (<code>LOOK</code>) sit at the top of the file. <code>poulpy-3d/poses.mjs</code> gives him his twelve poses, with what he wears and the effects around him. <code>poulpy-3d/motion.mjs</code> describes how he moves the same way: <code>TURN</code> is his idle, turning around in short steps with soft arms that trail and settle. <code>JUMP</code> is his little jump, <code>CHEER</code> the champion&#39;s jumps of joy, with his medal and confetti, and <code>WINK</code> the cocky one&#39;s wink, with his stars; they run live in the component workshop and are not written into the glTF files yet. <code>build-poulpy-pictures.mjs</code> paints his six moods and twelve poses as PNGs in <code>poulpy-3d/pictures</code>, with <code>poulpy-3d/picture.mjs</code>, in plain JavaScript so every machine writes the same pixels; CI checks them with <code>--check</code> too. <code>build-poulpy-3d.mjs</code> writes both as binary glTF files, one per side standing still and one per side moving, with his colours from <code>tokens.json</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> design/build-poulpy-3d.mjs</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Generated file</th><th>Used by</th></tr></thead><tbody><tr><td><code>design/poulpy-3d/poulpy_blue.glb</code></td><td>The blue, smiling side, for any 3D tool or engine</td></tr><tr><td><code>design/poulpy-3d/poulpy_ember.glb</code></td><td>The ember, grumpy side</td></tr><tr><td><code>design/poulpy-3d/poulpy_blue_turn.glb</code></td><td>The blue side, rigged, with the animation <code>turn</code></td></tr><tr><td><code>design/poulpy-3d/poulpy_ember_turn.glb</code></td><td>The ember side, rigged, with the animation <code>turn</code></td></tr></tbody></table><p>The script writes the files itself, byte for byte the same on every machine, and CI runs it with <code>--check</code>. The Brand &gt; Poulpy in 3D page of the component workshop (<a href="https://github.com/tkint/coach-poulpy/blob/main/web/storybook/stories/brand/Poulpy3d.mdx" target="_blank" rel="noreferrer"><code>web/storybook/stories/brand/Poulpy3d.mdx</code></a> and the live model) draws the same <code>model.mjs</code> and runs the same <code>motion.mjs</code> live, lists the rules of the shape and of the move and says how to reuse it; the apps do not use the model yet.</p><p>The rules for using Poulpy are in <a href="https://github.com/tkint/coach-poulpy/tree/main/web/storybook/stories/brand/" target="_blank" rel="noreferrer"><code>web/storybook/stories/brand/</code></a>; the full brand book is in <code>web/storybook/stories/brand/brand-book/</code> and on the Brand &gt; Brand book page of the component workshop, and the decisions behind it are in <a href="https://github.com/tkint/coach-poulpy/blob/main/web/storybook/stories/brand/Decisions.mdx" target="_blank" rel="noreferrer"><code>web/storybook/stories/brand/Decisions.mdx</code></a>.</p><h2 id="icons" tabindex="-1">Icons <a class="header-anchor" href="#icons" aria-label="Permalink to &quot;Icons&quot;">​</a></h2><p>Every icon is from <a href="https://lucide.dev" target="_blank" rel="noreferrer">Lucide</a> (<a href="./../docs/adr/0024-lucide-is-the-icon-set">ADR 0024</a>). <code>icons/</code> holds a copy of each Lucide icon the product uses, unchanged from the <code>lucide-static</code> package at the version <code>web/ui</code> pins for <code>@lucide/vue</code>, with Lucide&#39;s licence (<code>icons/LICENSE</code>). <code>build-icons.mjs</code> writes them for the apps:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> design/build-icons.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> calendar-plus</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # copy a Lucide icon in, then write</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> design/build-icons.mjs</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                       # write the apps&#39; icons again</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Generated file</th><th>Used by</th></tr></thead><tbody><tr><td><code>app-android/.../ui/Lucide.kt</code></td><td>Compose <code>ImageVector</code>s, one per icon (<code>Icon(Lucide.CalendarPlus, …)</code>)</td></tr><tr><td><code>app-ios/CoachPoulpy/Lucide.swift</code></td><td>The <code>Lucide</code> enum (<code>.calendarPlus</code>), the <code>LucideIcon</code> view and <code>Label(_:lucide:)</code></td></tr><tr><td><code>app-ios/CoachPoulpy/Assets.xcassets/Lucide/*.imageset</code></td><td>iOS template vector images (<code>LucideCalendarPlus</code>)</td></tr></tbody></table><p>The websites and the phone mockups take the same icons from <code>@lucide/vue</code> by name (<code>MobileIcon</code> in the phone stories), so a mockup cannot draw an icon other than the one it names. CI runs <code>build-icons.mjs --check</code>, which also fails when an image set is left over from an icon no longer in <code>icons/</code>. To move to a newer Lucide, raise <code>@lucide/vue</code> in <code>web/ui</code> and the docs site, then copy each icon again with <code>--add</code>.</p>`,33)])])}const m=o(a,[["render",i]]);export{u as __pageData,m as default};
